# (Türkçe, Deutsch, Français, Español)
HK=[("1. Yolculuk · A1",[
("Yusuf yirmi iki yaşında genç bir adam.","Yusuf ist ein junger Mann von zweiundzwanzig Jahren.","Yusuf est un jeune homme de vingt-deux ans.","Yusuf es un joven de veintidós años."),
("Türkiye'de, küçük bir kasabada yaşıyor.","Er lebt in einer kleinen Stadt in der Türkei.","Il habite dans une petite ville en Turquie.","Vive en un pueblo pequeño de Turquía."),
("Bir gün büyük bir haber alıyor.","Eines Tages bekommt er eine große Nachricht.","Un jour, il reçoit une grande nouvelle.","Un día recibe una gran noticia."),
("Yurt dışında bir üniversiteden burs kazanmış.","Er hat ein Stipendium an einer Universität im Ausland gewonnen.","Il a gagné une bourse dans une université à l'étranger.","Ha ganado una beca en una universidad extranjera."),
("Annesi hem sevinçli hem de biraz üzgün.","Seine Mutter ist froh, aber auch ein bisschen traurig.","Sa mère est contente, mais aussi un peu triste.","Su madre está contenta, pero también un poco triste."),
("\"Oğlum, seni çok özleyeceğim\" diyor.","„Mein Sohn, ich werde dich sehr vermissen“, sagt sie.","« Mon fils, tu vas beaucoup me manquer », dit-elle.","«Hijo mío, te voy a echar mucho de menos», dice."),
("Babası ona küçük bir Kur'an hediye ediyor.","Sein Vater schenkt ihm einen kleinen Koran.","Son père lui offre un petit Coran.","Su padre le regala un Corán pequeño."),
("Yusuf bavulunu hazırlıyor: kıyafetler, kitaplar ve bir seccade.","Yusuf packt seinen Koffer: Kleidung, Bücher und einen Gebetsteppich.","Yusuf prépare sa valise : des vêtements, des livres et un tapis de prière.","Yusuf prepara su maleta: ropa, libros y una alfombra de oración."),
("Sabah erkenden havaalanına gidiyorlar.","Früh am Morgen fahren sie zum Flughafen.","Tôt le matin, ils vont à l'aéroport.","Por la mañana temprano van al aeropuerto."),
("Uçak üç saat sonra yeni şehre iniyor.","Nach drei Stunden landet das Flugzeug in der neuen Stadt.","Trois heures plus tard, l'avion atterrit dans la nouvelle ville.","Tres horas después, el avión aterriza en la nueva ciudad."),
("Hava soğuk ve yağmurlu.","Das Wetter ist kalt und regnerisch.","Il fait froid et il pleut.","Hace frío y llueve."),
("Yusuf derin bir nefes alıyor ve \"Bismillah\" diyor.","Yusuf atmet tief ein und sagt: „Bismillah.“","Yusuf respire profondément et dit : « Bismillah. »","Yusuf respira hondo y dice: «Bismillah».")]),
("2. Yeni ev · A1",[
("Yusuf taksiyle yeni adresine gidiyor.","Yusuf fährt mit dem Taxi zu seiner neuen Adresse.","Yusuf va à sa nouvelle adresse en taxi.","Yusuf va a su nueva dirección en taxi."),
("Ev eski ama temiz bir binada.","Die Wohnung ist in einem alten, aber sauberen Haus.","L'appartement est dans un immeuble ancien mais propre.","El piso está en un edificio antiguo pero limpio."),
("Dairesi üçüncü katta, asansör yok.","Seine Wohnung ist im dritten Stock, und es gibt keinen Aufzug.","Son appartement est au troisième étage, et il n'y a pas d'ascenseur.","Su piso está en el tercer piso y no hay ascensor."),
("Ağır bavulunu merdivenlerden taşıyor.","Er trägt seinen schweren Koffer die Treppe hinauf.","Il monte sa lourde valise par l'escalier.","Sube su maleta pesada por las escaleras."),
("Oda küçük: bir yatak, bir masa ve bir dolap var.","Das Zimmer ist klein: Es gibt ein Bett, einen Tisch und einen Schrank.","La chambre est petite : il y a un lit, une table et une armoire.","La habitación es pequeña: hay una cama, una mesa y un armario."),
("Pencereden bir park görünüyor.","Vom Fenster aus sieht man einen Park.","De la fenêtre, on voit un parc.","Desde la ventana se ve un parque."),
("Yusuf önce kıbleyi buluyor.","Zuerst sucht Yusuf die Gebetsrichtung.","D'abord, Yusuf cherche la direction de la qibla.","Primero, Yusuf busca la dirección de la alquibla."),
("Telefonundaki pusula ona yardım ediyor.","Der Kompass auf seinem Handy hilft ihm.","La boussole de son téléphone l'aide.","La brújula de su móvil le ayuda."),
("Seccadesini pencerenin yanına seriyor.","Er legt seinen Gebetsteppich neben das Fenster.","Il pose son tapis de prière près de la fenêtre.","Pone su alfombra de oración junto a la ventana."),
("Sonra annesini arıyor.","Dann ruft er seine Mutter an.","Ensuite, il appelle sa mère.","Luego llama a su madre."),
("\"Anne, geldim. Her şey yolunda\" diyor.","„Mama, ich bin angekommen. Alles ist gut“, sagt er.","« Maman, je suis arrivé. Tout va bien », dit-il.","«Mamá, ya he llegado. Todo va bien», dice."),
("O gece yorgun ama mutlu uyuyor.","In dieser Nacht schläft er müde, aber glücklich.","Cette nuit-là, il dort fatigué mais heureux.","Esa noche duerme cansado pero feliz.")]),
("3. Market · A1",[
("Ertesi sabah buzdolabı boş.","Am nächsten Morgen ist der Kühlschrank leer.","Le lendemain matin, le réfrigérateur est vide.","A la mañana siguiente, la nevera está vacía."),
("Yusuf yakındaki markete gidiyor.","Yusuf geht in den Supermarkt in der Nähe.","Yusuf va au supermarché du quartier.","Yusuf va al supermercado de al lado."),
("Bir sepet alıyor ve reyonlara bakıyor.","Er nimmt einen Korb und schaut sich die Regale an.","Il prend un panier et regarde les rayons.","Coge una cesta y mira las estanterías."),
("Ekmek, süt, yumurta, peynir ve elma alıyor.","Er kauft Brot, Milch, Eier, Käse und Äpfel.","Il achète du pain, du lait, des œufs, du fromage et des pommes.","Compra pan, leche, huevos, queso y manzanas."),
("Et reyonunda helal et arıyor ama bulamıyor.","An der Fleischtheke sucht er Halal-Fleisch, aber er findet keins.","Au rayon boucherie, il cherche de la viande halal, mais il n'en trouve pas.","En la carnicería busca carne halal, pero no la encuentra."),
("Bir çalışana soruyor: \"Helal et var mı?\"","Er fragt einen Mitarbeiter: „Haben Sie Halal-Fleisch?“","Il demande à un employé : « Vous avez de la viande halal ? »","Pregunta a un empleado: «¿Tienen carne halal?»"),
("\"Burada yok ama köşede bir Türk kasabı var\" diyor adam.","„Hier nicht, aber an der Ecke gibt es einen türkischen Metzger“, sagt der Mann.","« Pas ici, mais il y a une boucherie turque au coin de la rue », dit l'homme.","«Aquí no, pero en la esquina hay una carnicería turca», dice el hombre."),
("Yusuf kasada sırayla bekliyor.","Yusuf wartet an der Kasse in der Schlange.","Yusuf fait la queue à la caisse.","Yusuf hace cola en la caja."),
("Kasiyer \"Poşet ister misiniz?\" diye soruyor.","Die Kassiererin fragt: „Brauchen Sie eine Tüte?“","La caissière demande : « Vous voulez un sac ? »","La cajera pregunta: «¿Quiere una bolsa?»"),
("\"Hayır, teşekkürler. Çantam var\" diyor Yusuf.","„Nein, danke. Ich habe eine Tasche“, sagt Yusuf.","« Non, merci. J'ai un sac », dit Yusuf.","«No, gracias. Tengo una bolsa», dice Yusuf."),
("Sonra kasaba gidiyor ve tavuk alıyor.","Dann geht er zum Metzger und kauft Hähnchen.","Ensuite, il va chez le boucher et achète du poulet.","Después va a la carnicería y compra pollo."),
("Akşam ilk yemeğini kendi pişiriyor.","Am Abend kocht er sein erstes Essen selbst.","Le soir, il prépare son premier repas lui-même.","Por la noche cocina su primera comida él solo.")]),
("4. Üniversitede ilk gün · A2",[
("Pazartesi günü dersler başlıyor.","Am Montag beginnen die Vorlesungen.","Lundi, les cours commencent.","El lunes empiezan las clases."),
("Kampüs çok büyük ve Yusuf biraz kayboluyor.","Der Campus ist sehr groß, und Yusuf verläuft sich ein bisschen.","Le campus est très grand et Yusuf se perd un peu.","El campus es muy grande y Yusuf se pierde un poco."),
("Bir kıza soruyor: \"Kütüphane nerede?\"","Er fragt ein Mädchen: „Wo ist die Bibliothek?“","Il demande à une fille : « Où est la bibliothèque ? »","Le pregunta a una chica: «¿Dónde está la biblioteca?»"),
("Kızın adı Meryem; o da yabancı bir öğrenci.","Das Mädchen heißt Meryem; sie ist auch eine ausländische Studentin.","La fille s'appelle Meryem ; elle aussi est une étudiante étrangère.","La chica se llama Meryem; también es una estudiante extranjera."),
("Meryem Bosnalı ve tıp okuyor.","Meryem kommt aus Bosnien und studiert Medizin.","Meryem vient de Bosnie et étudie la médecine.","Meryem es de Bosnia y estudia Medicina."),
("Yusuf ise mühendislik okuyor.","Yusuf studiert Ingenieurwesen.","Yusuf, lui, étudie l'ingénierie.","Yusuf, en cambio, estudia Ingeniería."),
("İlk ders matematik; hoca hızlı konuşuyor.","Die erste Vorlesung ist Mathematik; der Professor spricht schnell.","Le premier cours est un cours de maths ; le professeur parle vite.","La primera clase es de matemáticas; el profesor habla rápido."),
("Yusuf her şeyi anlamıyor ama not alıyor.","Yusuf versteht nicht alles, aber er macht sich Notizen.","Yusuf ne comprend pas tout, mais il prend des notes.","Yusuf no lo entiende todo, pero toma apuntes."),
("Dersten sonra hocaya gidiyor.","Nach der Vorlesung geht er zum Professor.","Après le cours, il va voir le professeur.","Después de la clase va a hablar con el profesor."),
("\"Affedersiniz, daha yavaş konuşabilir misiniz?\" diye soruyor.","„Entschuldigung, können Sie bitte langsamer sprechen?“, fragt er.","« Excusez-moi, pouvez-vous parler plus lentement ? » demande-t-il.","«Perdone, ¿puede hablar más despacio?», pregunta."),
("Hoca gülümsüyor: \"Tabii, ve sorularınız için ofisim açık.\"","Der Professor lächelt: „Natürlich, und mein Büro ist offen für Ihre Fragen.“","Le professeur sourit : « Bien sûr, et mon bureau est ouvert pour vos questions. »","El profesor sonríe: «Claro, y mi despacho está abierto para sus preguntas»."),
("Yusuf o gün çok şey öğreniyor, sadece matematik değil.","An diesem Tag lernt Yusuf viel, nicht nur Mathematik.","Ce jour-là, Yusuf apprend beaucoup de choses, pas seulement les maths.","Ese día Yusuf aprende mucho, no solo matemáticas.")]),
("5. Cuma namazı · A2",[
("Cuma günü Yusuf'un dersi öğlene kadar.","Am Freitag hat Yusuf bis Mittag Unterricht.","Le vendredi, Yusuf a cours jusqu'à midi.","El viernes Yusuf tiene clase hasta el mediodía."),
("Meryem ona şehirdeki büyük camiyi anlatıyor.","Meryem erzählt ihm von der großen Moschee in der Stadt.","Meryem lui parle de la grande mosquée de la ville.","Meryem le habla de la gran mezquita de la ciudad."),
("Cami tramvayla on beş dakika uzaklıkta.","Die Moschee ist fünfzehn Minuten mit der Straßenbahn entfernt.","La mosquée est à quinze minutes en tramway.","La mezquita está a quince minutos en tranvía."),
("Yusuf erken çıkıyor ve abdestini camide alıyor.","Yusuf fährt früh los und nimmt die Waschung in der Moschee.","Yusuf part tôt et fait ses ablutions à la mosquée.","Yusuf sale temprano y hace la ablución en la mezquita."),
("Cami dolu; insanlar birçok farklı ülkeden.","Die Moschee ist voll; die Menschen kommen aus vielen verschiedenen Ländern.","La mosquée est pleine ; les gens viennent de nombreux pays différents.","La mezquita está llena; la gente viene de muchos países distintos."),
("Türkler, Araplar, Afrikalılar ve yeni Müslümanlar yan yana oturuyor.","Türken, Araber, Afrikaner und neue Muslime sitzen nebeneinander.","Des Turcs, des Arabes, des Africains et de nouveaux musulmans sont assis côte à côte.","Turcos, árabes, africanos y nuevos musulmanes se sientan uno al lado del otro."),
("Hutbe önce Arapça, sonra şehrin dilinde okunuyor.","Die Predigt ist zuerst auf Arabisch, dann in der Sprache der Stadt.","Le sermon est d'abord en arabe, puis dans la langue du pays.","El sermón es primero en árabe y luego en el idioma del país."),
("Konu komşu hakları.","Das Thema sind die Rechte der Nachbarn.","Le thème, ce sont les droits des voisins.","El tema son los derechos de los vecinos."),
("Namazdan sonra yaşlı bir amca Yusuf'u selamlıyor.","Nach dem Gebet grüßt ein älterer Herr Yusuf.","Après la prière, un vieux monsieur salue Yusuf.","Después de la oración, un señor mayor saluda a Yusuf."),
("\"Yenisin galiba. Hoş geldin evlat!\"","„Du bist wohl neu hier. Willkommen, mein Junge!“","« Tu es nouveau, je crois. Bienvenue, mon fils ! »","«Eres nuevo, ¿verdad? ¡Bienvenido, hijo!»"),
("Amca onu cumartesi akşamı yemeğe davet ediyor.","Der Herr lädt ihn für Samstagabend zum Essen ein.","Le monsieur l'invite à dîner samedi soir.","El señor lo invita a cenar el sábado por la noche."),
("Yusuf bu şehirde artık yalnız olmadığını hissediyor.","Yusuf spürt, dass er in dieser Stadt nicht mehr allein ist.","Yusuf sent qu'il n'est plus seul dans cette ville.","Yusuf siente que ya no está solo en esta ciudad.")]),
("6. Misafirlik · A2",[
("Cumartesi akşamı Yusuf, Hasan amcanın evine gidiyor.","Am Samstagabend geht Yusuf zu Onkel Hasan nach Hause.","Samedi soir, Yusuf va chez l'oncle Hassan.","El sábado por la noche, Yusuf va a casa del tío Hasan."),
("Elinde bir kutu tatlı var.","Er hat eine Schachtel Süßigkeiten in der Hand.","Il a une boîte de pâtisseries à la main.","Lleva una caja de dulces en la mano."),
("Hasan amca kırk yıl önce bu şehre gelmiş.","Onkel Hasan ist vor vierzig Jahren in diese Stadt gekommen.","L'oncle Hassan est arrivé dans cette ville il y a quarante ans.","El tío Hasan llegó a esta ciudad hace cuarenta años."),
("O zamanlar bir fabrikada çalışıyormuş.","Damals hat er in einer Fabrik gearbeitet.","À l'époque, il travaillait dans une usine.","En aquella época trabajaba en una fábrica."),
("Şimdi emekli ve torunlarıyla vakit geçiriyor.","Jetzt ist er in Rente und verbringt Zeit mit seinen Enkeln.","Maintenant, il est à la retraite et passe du temps avec ses petits-enfants.","Ahora está jubilado y pasa tiempo con sus nietos."),
("Masada çorba, pilav, et ve salata var.","Auf dem Tisch gibt es Suppe, Reis, Fleisch und Salat.","Sur la table, il y a de la soupe, du riz, de la viande et de la salade.","En la mesa hay sopa, arroz, carne y ensalada."),
("Hasan amcanın eşi \"Ye evladım, utanma\" diyor.","Onkel Hasans Frau sagt: „Iss, mein Kind, sei nicht schüchtern.“","La femme de l'oncle Hassan dit : « Mange, mon enfant, ne sois pas timide. »","La esposa del tío Hasan dice: «Come, hijo, no tengas vergüenza»."),
("Yemekten sonra çay içip sohbet ediyorlar.","Nach dem Essen trinken sie Tee und unterhalten sich.","Après le repas, ils boivent du thé et discutent.","Después de la cena toman té y charlan."),
("Hasan amca ilk yıllarını anlatıyor.","Onkel Hasan erzählt von seinen ersten Jahren.","L'oncle Hassan raconte ses premières années.","El tío Hasan cuenta sus primeros años."),
("\"Dili bilmeden her şey zordu\" diyor.","„Ohne die Sprache war alles schwer“, sagt er.","« Sans la langue, tout était difficile », dit-il.","«Sin el idioma, todo era difícil», dice."),
("\"Her gün biraz öğren; dil sabır ister.\"","„Lern jeden Tag ein bisschen; eine Sprache braucht Geduld.“","« Apprends un peu chaque jour ; une langue demande de la patience. »","«Aprende un poco cada día; un idioma necesita paciencia»."),
("Yusuf bu öğüdü defterine yazıyor.","Yusuf schreibt diesen Rat in sein Heft.","Yusuf écrit ce conseil dans son cahier.","Yusuf escribe ese consejo en su cuaderno.")]),
("7. Hastalık · A2",[
("Kasım ayında Yusuf hastalanıyor.","Im November wird Yusuf krank.","En novembre, Yusuf tombe malade.","En noviembre, Yusuf se pone enfermo."),
("Boğazı ağrıyor ve ateşi var.","Er hat Halsschmerzen und Fieber.","Il a mal à la gorge et de la fièvre.","Le duele la garganta y tiene fiebre."),
("Derse gidemiyor ve yatakta kalıyor.","Er kann nicht zur Uni gehen und bleibt im Bett.","Il ne peut pas aller en cours et reste au lit.","No puede ir a clase y se queda en la cama."),
("Meryem mesaj atıyor: \"Bugün neredesin?\"","Meryem schreibt eine Nachricht: „Wo bist du heute?“","Meryem envoie un message : « Où es-tu aujourd'hui ? »","Meryem le escribe: «¿Dónde estás hoy?»"),
("Yusuf hasta olduğunu yazıyor.","Yusuf schreibt, dass er krank ist.","Yusuf écrit qu'il est malade.","Yusuf le escribe que está enfermo."),
("Meryem tıp öğrencisi olduğu için ona öğütler veriyor.","Weil Meryem Medizin studiert, gibt sie ihm Ratschläge.","Comme Meryem étudie la médecine, elle lui donne des conseils.","Como Meryem estudia Medicina, le da consejos."),
("\"Bol su iç, dinlen ve ateşin düşmezse doktora git.\"","„Trink viel, ruh dich aus, und wenn das Fieber nicht sinkt, geh zum Arzt.“","« Bois beaucoup, repose-toi, et si la fièvre ne baisse pas, va chez le médecin. »","«Bebe mucha agua, descansa y, si no te baja la fiebre, ve al médico»."),
("Ertesi gün Yusuf doktordan randevu alıyor.","Am nächsten Tag macht Yusuf einen Termin beim Arzt.","Le lendemain, Yusuf prend rendez-vous chez le médecin.","Al día siguiente, Yusuf pide cita con el médico."),
("Doktor onu muayene ediyor ve ilaç yazıyor.","Der Arzt untersucht ihn und verschreibt ein Medikament.","Le médecin l'examine et lui prescrit un médicament.","El médico lo examina y le receta un medicamento."),
("Eczanede ilacı alıyor.","In der Apotheke holt er das Medikament.","Il prend le médicament à la pharmacie.","Recoge el medicamento en la farmacia."),
("Hasan amca ona ev yapımı çorba getiriyor.","Onkel Hasan bringt ihm selbstgemachte Suppe.","L'oncle Hassan lui apporte de la soupe faite maison.","El tío Hasan le trae sopa casera."),
("Bir hafta sonra Yusuf iyileşiyor ve Allah'a şükrediyor.","Nach einer Woche ist Yusuf wieder gesund und dankt Allah.","Une semaine plus tard, Yusuf est guéri et remercie Allah.","Una semana después, Yusuf se cura y da gracias a Allah.")]),
("8. Sınav · B1",[
("Ocak ayında sınavlar yaklaşıyor.","Im Januar kommen die Prüfungen näher.","En janvier, les examens approchent.","En enero se acercan los exámenes."),
("Yusuf ve Meryem her gün kütüphanede çalışıyor.","Yusuf und Meryem lernen jeden Tag in der Bibliothek.","Yusuf et Meryem étudient tous les jours à la bibliothèque.","Yusuf y Meryem estudian todos los días en la biblioteca."),
("Yusuf'un en büyük korkusu matematik sınavı.","Yusufs größte Angst ist die Matheprüfung.","La plus grande peur de Yusuf, c'est l'examen de maths.","El mayor miedo de Yusuf es el examen de matemáticas."),
("Geceleri geç saatlere kadar problem çözüyor.","Abends löst er bis spät in die Nacht Aufgaben.","Le soir, il résout des exercices jusque tard dans la nuit.","Por la noche resuelve problemas hasta muy tarde."),
("Bazen yoruluyor ve vazgeçmek istiyor.","Manchmal ist er müde und möchte aufgeben.","Parfois, il est fatigué et veut abandonner.","A veces se cansa y quiere rendirse."),
("O zaman babasının sözünü hatırlıyor: \"Çalış, sonra tevekkül et.\"","Dann erinnert er sich an die Worte seines Vaters: „Arbeite, und dann vertraue auf Allah.“","Alors il se souvient des paroles de son père : « Travaille, puis remets-t'en à Allah. »","Entonces recuerda las palabras de su padre: «Trabaja y luego confía en Allah»."),
("Sınav sabahı sabah namazını kılıp dua ediyor.","Am Morgen der Prüfung betet er das Morgengebet und macht Bittgebete.","Le matin de l'examen, il fait la prière de l'aube et des invocations.","La mañana del examen reza la oración del alba y hace súplicas."),
("Sınav salonu sessiz ve soğuk.","Der Prüfungsraum ist still und kalt.","La salle d'examen est silencieuse et froide.","La sala del examen está silenciosa y fría."),
("İlk soru kolay, ikincisi zor.","Die erste Frage ist leicht, die zweite ist schwer.","La première question est facile, la deuxième est difficile.","La primera pregunta es fácil; la segunda, difícil."),
("Yusuf sakin kalıyor ve adım adım düşünüyor.","Yusuf bleibt ruhig und denkt Schritt für Schritt nach.","Yusuf reste calme et réfléchit étape par étape.","Yusuf mantiene la calma y piensa paso a paso."),
("İki hafta sonra sonuçlar açıklanıyor.","Zwei Wochen später kommen die Ergebnisse.","Deux semaines plus tard, les résultats sont publiés.","Dos semanas después salen los resultados."),
("Yusuf geçmiş, hem de iyi bir notla!","Yusuf hat bestanden, und zwar mit einer guten Note!","Yusuf a réussi, et avec une bonne note !","¡Yusuf ha aprobado, y con buena nota!")]),
("9. Ramazan · B1",[
("Mart ayında Ramazan başlıyor.","Im März beginnt der Ramadan.","En mars, le Ramadan commence.","En marzo empieza el Ramadán."),
("Burada günler uzun; oruç on dört saat sürüyor.","Hier sind die Tage lang; das Fasten dauert vierzehn Stunden.","Ici, les journées sont longues ; le jeûne dure quatorze heures.","Aquí los días son largos; el ayuno dura catorce horas."),
("Yusuf sahura kalkmak için alarm kuruyor.","Yusuf stellt einen Wecker, um zum Sahur aufzustehen.","Yusuf met un réveil pour se lever pour le sahour.","Yusuf pone una alarma para levantarse para el suhur."),
("Bazı arkadaşları orucu merak ediyor.","Einige seiner Freunde sind neugierig auf das Fasten.","Certains de ses amis sont curieux au sujet du jeûne.","Algunos de sus amigos sienten curiosidad por el ayuno."),
("\"Gerçekten su da mı içmiyorsun?\" diye soruyor biri.","„Trinkst du wirklich auch kein Wasser?“, fragt einer.","« Tu ne bois vraiment pas d'eau non plus ? » demande l'un d'eux.","«¿De verdad tampoco bebes agua?», pregunta uno."),
("Yusuf sabırla anlatıyor: \"Oruç bana açları anlamayı öğretiyor.\"","Yusuf erklärt geduldig: „Das Fasten lehrt mich, die Hungernden zu verstehen.“","Yusuf explique patiemment : « Le jeûne m'apprend à comprendre ceux qui ont faim. »","Yusuf explica con paciencia: «El ayuno me enseña a entender a los que pasan hambre»."),
("Camide her akşam iftar veriliyor.","In der Moschee gibt es jeden Abend ein Fastenbrechen.","À la mosquée, il y a une rupture du jeûne chaque soir.","En la mezquita se sirve el iftar todas las noches."),
("Yusuf orada gönüllü olarak çalışıyor.","Yusuf hilft dort ehrenamtlich mit.","Yusuf y travaille comme bénévole.","Yusuf trabaja allí como voluntario."),
("Masaları kuruyor, hurma ve su dağıtıyor.","Er stellt Tische auf und verteilt Datteln und Wasser.","Il installe les tables et distribue des dattes et de l'eau.","Monta las mesas y reparte dátiles y agua."),
("Bir akşam üniversiteden arkadaşlarını da iftara davet ediyor.","Eines Abends lädt er auch seine Freunde von der Uni zum Fastenbrechen ein.","Un soir, il invite aussi ses amis de l'université à l'iftar.","Una noche invita también a sus amigos de la universidad al iftar."),
("Arkadaşları bu kalabalık ve sıcak sofrayı çok seviyor.","Seine Freunde lieben diesen vollen, herzlichen Tisch.","Ses amis adorent cette table pleine et chaleureuse.","A sus amigos les encanta esa mesa llena y acogedora."),
("Bayram sabahı Yusuf annesini görüntülü arıyor ve ağlıyor.","Am Morgen des Festes ruft Yusuf seine Mutter per Video an und weint.","Le matin de l'Aïd, Yusuf appelle sa mère en vidéo et pleure.","La mañana del Eid, Yusuf hace una videollamada a su madre y llora.")]),
("10. Bir yıl sonra · B1",[
("Bir yıl geçti; Yusuf artık dili iyi konuşuyor.","Ein Jahr ist vergangen; Yusuf spricht die Sprache jetzt gut.","Un an a passé ; Yusuf parle maintenant bien la langue.","Ha pasado un año; Yusuf ya habla bien el idioma."),
("Yeni gelen öğrencilere şehri gösteriyor.","Er zeigt neuen Studenten die Stadt.","Il fait visiter la ville aux nouveaux étudiants.","Les enseña la ciudad a los estudiantes nuevos."),
("Onlara marketi, camiyi ve kütüphaneyi tanıtıyor.","Er zeigt ihnen den Supermarkt, die Moschee und die Bibliothek.","Il leur montre le supermarché, la mosquée et la bibliothèque.","Les muestra el supermercado, la mezquita y la biblioteca."),
("Bir zamanlar kendisine yardım edildiğini unutmuyor.","Er vergisst nicht, dass man ihm einmal geholfen hat.","Il n'oublie pas qu'on l'a aidé autrefois.","No olvida que una vez le ayudaron a él."),
("Hasan amcanın öğüdünü onlara da söylüyor.","Er gibt ihnen auch den Rat von Onkel Hasan weiter.","Il leur transmet aussi le conseil de l'oncle Hassan.","También les transmite el consejo del tío Hasan."),
("Meryem ile birlikte bir yardımlaşma grubu kuruyorlar.","Zusammen mit Meryem gründet er eine Hilfsgruppe.","Avec Meryem, il crée un groupe d'entraide.","Junto con Meryem crean un grupo de ayuda mutua."),
("Grup, yalnız yaşayan yaşlılara alışveriş yapıyor.","Die Gruppe kauft für ältere Menschen ein, die allein leben.","Le groupe fait les courses pour les personnes âgées qui vivent seules.","El grupo hace la compra a las personas mayores que viven solas."),
("Yaz tatilinde Yusuf memleketine dönüyor.","In den Sommerferien kehrt Yusuf in seine Heimat zurück.","Pendant les vacances d'été, Yusuf rentre dans son pays.","En las vacaciones de verano, Yusuf vuelve a su tierra."),
("Annesi onu havaalanında sımsıkı kucaklıyor.","Seine Mutter umarmt ihn am Flughafen ganz fest.","Sa mère le serre très fort dans ses bras à l'aéroport.","Su madre lo abraza muy fuerte en el aeropuerto."),
("\"Değişmişsin oğlum, büyümüşsün\" diyor.","„Du hast dich verändert, mein Sohn, du bist erwachsen geworden“, sagt sie.","« Tu as changé, mon fils, tu as grandi », dit-elle.","«Has cambiado, hijo, te has hecho mayor», dice."),
("Yusuf gülümsüyor: \"Gurbet bana çok şey öğretti.\"","Yusuf lächelt: „Die Fremde hat mich viel gelehrt.“","Yusuf sourit : « L'exil m'a beaucoup appris. »","Yusuf sonríe: «Vivir lejos me ha enseñado mucho»."),
("\"En çok da sabrı ve şükrü.\"","„Vor allem Geduld und Dankbarkeit.“","« Surtout la patience et la gratitude. »","«Sobre todo, la paciencia y la gratitud».")])]
